/**
 * Resolves platform-managed storage bindings for hosted deployments.
 */
import { readFileSync } from "node:fs";
export const DEFAULT_AGENT_SERVE_STORE_SOURCE_ID_FILE = "/run/cursor/secrets/AGENT_SERVE_STORE_SOURCE_ID";
export const DEFAULT_AGENT_SERVE_FRAMEWORK_STORE_SOURCE_ID_FILE = "/run/cursor/secrets/AGENT_SERVE_FRAMEWORK_STORE_SOURCE_ID";
export const DEFAULT_AGENT_SERVE_STORE_PROTOCOL_FILE = "/run/cursor/secrets/AGENT_SERVE_STORE_PROTOCOL";
/**
 * Transport mode that enables batched file operations. Unknown values use
 * the compatibility transport.
 */
export const AGENT_SERVE_FACTORY_FLUSH_PROTOCOL = "factory-flush-v1";
/**
 * Transport mode that adds managed domain operations to
 * {@link AGENT_SERVE_FACTORY_FLUSH_PROTOCOL}.
 */
export const AGENT_SERVE_FACTORY_API_PROTOCOL = "factory-api-v1";
/** True when the transport supports batched file operations. */
export function storeProtocolEnablesFactoryFlush(protocol) {
    return (protocol === AGENT_SERVE_FACTORY_FLUSH_PROTOCOL || protocol === AGENT_SERVE_FACTORY_API_PROTOCOL);
}
/** True when the transport supports managed domain operations. */
export function storeProtocolEnablesStoreApi(protocol) {
    return protocol === AGENT_SERVE_FACTORY_API_PROTOCOL;
}
const STORE_SOURCE_ID_ENV = "AGENT_SERVE_STORE_SOURCE_ID";
const FRAMEWORK_STORE_SOURCE_ID_ENV = "AGENT_SERVE_FRAMEWORK_STORE_SOURCE_ID";
const STORE_SOURCE_ID_FILE_ENV = "AGENT_SERVE_STORE_SOURCE_ID_FILE";
const FRAMEWORK_STORE_SOURCE_ID_FILE_ENV = "AGENT_SERVE_FRAMEWORK_STORE_SOURCE_ID_FILE";
const STORE_PROTOCOL_ENV = "AGENT_SERVE_STORE_PROTOCOL";
const STORE_PROTOCOL_FILE_ENV = "AGENT_SERVE_STORE_PROTOCOL_FILE";
function readTrimmedFile(path) {
    try {
        const raw = readFileSync(path, "utf8").trim();
        return raw === "" ? undefined : raw;
    }
    catch {
        return undefined;
    }
}
function readBoundSecretFile(fileEnvVar, defaultPath, env) {
    const configured = env[fileEnvVar]?.trim();
    const path = configured !== undefined && configured !== "" ? configured : defaultPath;
    return readTrimmedFile(path);
}
/** Resolve the author-facing managed file store. */
export function resolveDeploymentStoreSourceIdSync(env = process.env) {
    const fromEnv = env[STORE_SOURCE_ID_ENV]?.trim();
    if (fromEnv !== undefined && fromEnv !== "") {
        return fromEnv;
    }
    return readBoundSecretFile(STORE_SOURCE_ID_FILE_ENV, DEFAULT_AGENT_SERVE_STORE_SOURCE_ID_FILE, env);
}
/** Resolve the framework-only managed file store. */
export function resolveFrameworkStoreSourceIdSync(env = process.env) {
    const fromEnv = env[FRAMEWORK_STORE_SOURCE_ID_ENV]?.trim();
    if (fromEnv !== undefined && fromEnv !== "") {
        return fromEnv;
    }
    return readBoundSecretFile(FRAMEWORK_STORE_SOURCE_ID_FILE_ENV, DEFAULT_AGENT_SERVE_FRAMEWORK_STORE_SOURCE_ID_FILE, env);
}
/**
 * Resolve the managed-storage transport mode. Callers resolve it lazily so
 * platform updates take effect without recreating the storage client.
 */
export function resolveStoreProtocolSync(env = process.env) {
    const fromEnv = env[STORE_PROTOCOL_ENV]?.trim();
    if (fromEnv !== undefined && fromEnv !== "") {
        return fromEnv;
    }
    return readBoundSecretFile(STORE_PROTOCOL_FILE_ENV, DEFAULT_AGENT_SERVE_STORE_PROTOCOL_FILE, env);
}
/**
 * Resolve both managed architecture-v2 storage identities. Callers keep this
 * resolver lazy, and both identities are mandatory once storage is used.
 */
export function requireCursorManagedV2StoreIdsSync(env = process.env) {
    const deploymentStoreSourceId = resolveDeploymentStoreSourceIdSync(env);
    const frameworkStoreSourceId = resolveFrameworkStoreSourceIdSync(env);
    if (deploymentStoreSourceId === undefined || frameworkStoreSourceId === undefined) {
        throw new Error("Cursor-managed AgentSDK v2 requires AGENT_SERVE_STORE_SOURCE_ID and AGENT_SERVE_FRAMEWORK_STORE_SOURCE_ID");
    }
    return { deploymentStoreSourceId, frameworkStoreSourceId };
}
